import{_ as a,o as i,c as s,a5 as t}from"./chunks/framework.DrDMl0tG.js";const g=JSON.parse('{"title":"Logging System","description":"","frontmatter":{},"headers":[],"relativePath":"sections/LoggingSystem.md","filePath":"sections/LoggingSystem.md"}'),l={name:"sections/LoggingSystem.md"};function o(n,e,c,d,h,r){return i(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="logging-system" tabindex="-1">Logging System <a class="header-anchor" href="#logging-system" aria-label="Permalink to &quot;Logging System&quot;">​</a></h1><p>The RaiSim logging system, inspired by the <code>glog</code> library, provides one-line macros (<code>raisim/raisim_message.hpp</code>, included by <code>raisim/World.hpp</code>) that print a message together with a time stamp and its source location, in the form <code>[YYYY:MM:DD:HH:MM:SS file.cpp:42] message</code>. Messages are written only to standard output (<code>std::cout</code>); they are not saved to a file. The message argument can be anything that can be streamed with <code>&lt;&lt;</code>, e.g. <code>RSWARN(&quot;mass is &quot; &lt;&lt; mass)</code>. For instance, rather than:</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(fail) {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::cout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">date</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">FILENAME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LINENUMBER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ... </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;failed here </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    exit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>one may utilize:</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">RSFATAL_IF</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(fail, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;failed here&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>The available logging macros are as follows:</p><ul><li><code>RSINFO(msg)</code>: Prints the message in the default terminal color.</li><li><code>RSWARN(msg)</code>: Prints the message in yellow.</li><li><code>RSFATAL(msg)</code>: Prints the message in bold red and calls the fatal callback.</li><li><code>RSINFO_IF(con, msg)</code>: Prints the message in the default color if the condition evaluates to true.</li><li><code>RSWARN_IF(con, msg)</code>: Prints the message in yellow if the condition evaluates to true.</li><li><code>RSFATAL_IF(con, msg)</code>: Prints the message in bold red and calls the fatal callback if the condition evaluates to true.</li><li><code>RSASSERT(con, msg)</code>: Prints the message in bold red and calls the fatal callback if the condition evaluates to false. It is active in all builds.</li><li><code>RSRETURN_IF(con, msg)</code>: Prints the message in the default color and executes <code>return;</code> if the condition evaluates to true. Use it only in functions that return <code>void</code>.</li><li><code>RSISNAN(val)</code>: Prints <code>val is nan</code> (with the expression text in place of <code>val</code>) and calls the fatal callback if the value is NaN (Not a Number).</li><li><code>RSISNAN_MSG(val, msg)</code>: Prints the specified message and calls the fatal callback if the value is NaN.</li></ul><p><code>printf</code>-style variants take a format string and arguments: <code>RSINFOF</code>, <code>RSWARNF</code>, <code>RSFATALF</code>, <code>RSINFO_IFF</code>, <code>RSWARN_IFF</code>, <code>RSFATAL_IFF</code>, <code>RSASSERTF</code>, <code>RSRETURN_IFF</code>, and <code>RSISNAN_MSGF</code>, e.g. <code>RSWARNF(&quot;mass is %f&quot;, mass)</code>. The formatted message is truncated to 1023 characters.</p><h2 id="fatal-callback" tabindex="-1">Fatal callback <a class="header-anchor" href="#fatal-callback" aria-label="Permalink to &quot;Fatal callback&quot;">​</a></h2><p>By default, a fatal message calls <code>std::exit(1)</code>. Install a global callback to handle fatal errors differently, for example by throwing an exception that the application can catch:</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">raisim</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">RaiSimMsg</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setFatalCallback</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">([]() {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  throw</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">runtime_error</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;RaiSim fatal error; see the log above&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>Execution continues after the fatal macro if the callback returns, so a custom callback should normally throw or terminate. Do not use <code>[](){ throw; }</code>: a <code>throw;</code> without an exception being handled calls <code>std::terminate</code>. Passing an empty function restores the default.</p><p><code>RaiSimMsg::setThreadFatalCallback(callback)</code> installs a callback for the calling thread only; it takes precedence over the global callback on that thread and returns the thread&#39;s previous callback. The RAII helper <code>raisim::ScopedRaiSimFatalCallback</code> installs a thread callback and restores the previous one when it goes out of scope. Thread callbacks are kept by thread id, so remove one (pass an empty function, or let the scoped helper do it) before its thread exits; a callback left behind would be inherited by a later thread that is given the same id.</p><h2 id="debug-only-macros" tabindex="-1">Debug-only macros <a class="header-anchor" href="#debug-only-macros" aria-label="Permalink to &quot;Debug-only macros&quot;">​</a></h2><p>These macros impact performance; for example, all <code>_IF</code> macros involve boolean checks and potential branching.</p><p>To avoid performance overhead from branching in release builds, the following debug-only versions of the macros are available:</p><ul><li><code>DRSINFO(msg)</code></li><li><code>DRSWARN(msg)</code></li><li><code>DRSFATAL(msg)</code></li><li><code>DRSINFO_IF(con, msg)</code></li><li><code>DRSWARN_IF(con, msg)</code></li><li><code>DRSFATAL_IF(con, msg)</code></li><li><code>DRSASSERT(con, msg)</code></li><li><code>DRSRETURN_IF(con, msg)</code></li><li><code>DRSISNAN(val)</code></li><li><code>DRSISNAN_MSG(val, msg)</code></li></ul><p>They expand to the corresponding <code>RS*</code> macros only when <code>RSDEBUG</code> is defined, and to nothing otherwise; <code>printf</code>-style <code>DRS*F</code> variants exist as well. The exported <code>raisim::raisim</code> CMake target defines <code>RSDEBUG</code> when your build links the Debug RaiSim library, so a Debug build of your application has these checks only if the RaiSim package contains the Debug library (see <a href="./BuildAndTest.html">Build, Test, and Benchmark</a>).</p><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><h3 id="raisimmsg" tabindex="-1">RaiSimMsg <a class="header-anchor" href="#raisimmsg" aria-label="Permalink to &quot;RaiSimMsg&quot;">​</a></h3><ul><li><a href="/api/raisim/RaiSimMsg.html"><code>raisim::RaiSimMsg</code></a></li></ul>`,21)])])}const k=a(l,[["render",o]]);export{g as __pageData,k as default};
